/* Deep Field (dark mode): a slow flight through a solar system. Area background: static sky and sun.
   ::before: near stars zoom (GPU). ::after: bodies; depth falls on each one's clock, and size and offset scale by 1/depth. */
@property --sp-m { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes sp-m { to { --sp-m: 360deg; } }
@property --sp-a { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --sp-b { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --sp-c { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --sp-d { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --sp-e { syntax: "<number>"; inherits: false; initial-value: 0; }
@keyframes sp-a { to { --sp-a: 1; } }
@keyframes sp-b { to { --sp-b: 1; } }
@keyframes sp-c { to { --sp-c: 1; } }
@keyframes sp-d { to { --sp-d: 1; } }
@keyframes sp-e { to { --sp-e: 1; } }
@keyframes sp-zoom { 0% { transform: scale(1); opacity: 0; } 12% { opacity: .9; } 82% { opacity: .9; } 100% { transform: scale(2.2); opacity: 0; } }

