.dark:has([data-sidebar-row][aria-current="page"][aria-label*=", Working"]) [data-workspace-area="conversation"]::before {
  background: repeating-conic-gradient(#d4e4ff26 0 .25deg, #0000 0 2.5deg), var(--sp-stars) center / 600px 600px repeat;
  mask: repeating-radial-gradient(#0000 0 22px, #000 0 70px), radial-gradient(#0000 10%, #000 50%); mask-composite: intersect;
  animation-duration: 7s;
}
@media (prefers-reduced-motion: reduce) { .dark [data-workspace-area="conversation"]::before, .dark [data-workspace-area="conversation"]::after { animation-play-state: paused !important; } }
